package com.triglav.clan.util;

import java.text.Normalizer;

/**
 * The game's own fonts (chat box, overlays) have no č/š/ž — they render as wrong glyphs. Text shown
 * inside the game is therefore folded to plain ASCII ("Čez 15 min" -> "Cez 15 min"). The side panel
 * uses RuneLite's Swing font and keeps the real letters.
 */
public final class GameText
{
	private GameText()
	{
	}

	public static String ascii(String text)
	{
		if (text == null)
		{
			return "";
		}

		final String folded = Normalizer.normalize(text, Normalizer.Form.NFD)
			.replaceAll("\\p{M}", "")
			.replace('—', '-')
			.replace('–', '-')
			.replace('»', '"')
			.replace('«', '"')
			.replace('„', '"')
			.replace('“', '"')
			.replace('”', '"')
			.replace('’', '\'');

		final StringBuilder out = new StringBuilder(folded.length());
		for (char c : folded.toCharArray())
		{
			if (c >= 32 && c < 127)
			{
				out.append(c);
			}
		}
		return out.toString();
	}
}

package com.triglav.clan.net;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.triglav.clan.TriglavConfig;
import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Turns the member's permanent clan code (TRG-XXXX from clan.kokalj.dev/profil) into the ingest key
 * every endpoint uses, via POST /api/plugin/link. The last key is cached in the config so the plugin
 * keeps working when the site is unreachable at startup. A value that isn't a TRG code is taken as
 * the raw ingest key itself (the key from the Dink URL still works).
 */
@Slf4j
@Singleton
public class KeyStore
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final String CACHED_KEY = "ingestKey";

	public enum Result
	{
		LINKED, WRONG_CODE, UNREACHABLE, EMPTY
	}

	private final OkHttpClient httpClient;
	private final TriglavConfig config;
	private final ConfigManager configManager;
	private final ScheduledExecutorService executor;

	private volatile String ingestKey;
	private volatile String linkedName;

	@Inject
	private KeyStore(OkHttpClient httpClient, TriglavConfig config, ConfigManager configManager, ScheduledExecutorService executor)
	{
		this.httpClient = httpClient;
		this.config = config;
		this.configManager = configManager;
		this.executor = executor;
		this.ingestKey = configManager.getConfiguration(TriglavConfig.GROUP, CACHED_KEY);
	}

	/** @return the ingest key, or null if not linked */
	public String ingestKey()
	{
		final String key = ingestKey;
		return key == null || key.isEmpty() ? null : key;
	}

	public boolean isLinked()
	{
		return ingestKey() != null;
	}

	/** @return the Discord name the code belongs to, once confirmed by the site this session */
	public String linkedName()
	{
		return linkedName;
	}

	/** Resolves the configured clan code off the client thread and reports the outcome. */
	public void refresh(Consumer<Result> onDone)
	{
		executor.execute(() -> onDone.accept(resolve()));
	}

	private Result resolve()
	{
		final String raw = config.clanCode() == null ? "" : config.clanCode().trim();
		if (raw.isEmpty())
		{
			store(null, null);
			return Result.EMPTY;
		}

		if (!isClanCode(raw))
		{
			store(raw, null);
			return Result.LINKED;
		}

		final HttpUrl url = HttpUrl.parse(ApiClient.siteUrl() + "/api/plugin/link");
		if (url == null)
		{
			return Result.UNREACHABLE;
		}

		final JsonObject body = new JsonObject();
		body.addProperty("code", raw);
		final Request request = new Request.Builder().url(url).post(RequestBody.create(JSON, body.toString())).build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (response.code() == 404)
			{
				store(null, null);
				return Result.WRONG_CODE;
			}
			if (!response.isSuccessful() || response.body() == null)
			{
				return Result.UNREACHABLE;
			}

			final JsonObject json = new JsonParser().parse(response.body().string()).getAsJsonObject();
			store(json.get("ingestKey").getAsString(), json.has("name") ? json.get("name").getAsString() : null);
			return Result.LINKED;
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Could not link clan code: {}", e.getMessage());
			return Result.UNREACHABLE;
		}
	}

	private void store(String key, String name)
	{
		ingestKey = key;
		linkedName = name;
		if (key == null)
		{
			configManager.unsetConfiguration(TriglavConfig.GROUP, CACHED_KEY);
		}
		else
		{
			configManager.setConfiguration(TriglavConfig.GROUP, CACHED_KEY, key);
		}
	}

	/** "TRG-2A3B", "trg 2a3b", "TRG2A3B" */
	static boolean isClanCode(String raw)
	{
		return raw.toUpperCase().replaceAll("[^A-Z0-9]", "").matches("TRG[A-Z0-9]{4}");
	}
}

package com.triglav.clan.net;

import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Talks to the clan site's ingest endpoint, which speaks the same envelope as Dink
 * (see docs/plugin-brief.md §2 in the site repo). Everything queues and drains off the
 * client thread, so a slow or unreachable site never stutters the game.
 */
@Slf4j
@Singleton
public class ApiClient
{
	/**
	 * Overridable with -Dtriglav.siteUrl=http://localhost:3000 for local development against
	 * `docker compose up` in the site repo. Production members never need to touch this.
	 */
	private static final String DEFAULT_SITE_URL = "https://clan.kokalj.dev";

	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	// PNG, not WebP: the JDK has no WebP encoder; the site converts every upload to WebP itself.
	private static final MediaType PNG = MediaType.parse("image/png");

	/** Queue cap from docs/plugin-brief.md §6. */
	private static final int MAX_QUEUE = 200;
	/** Give up on an individual event after this many failed attempts. */
	private static final int MAX_ATTEMPTS = 3;
	private static final int DRAIN_INTERVAL_SECONDS = 5;

	private final OkHttpClient httpClient;
	private final KeyStore keyStore;
	private final Deque<QueuedEvent> queue = new ArrayDeque<>();

	@Inject
	private ApiClient(OkHttpClient httpClient, KeyStore keyStore, ScheduledExecutorService executor)
	{
		this.httpClient = httpClient;
		this.keyStore = keyStore;
		executor.scheduleWithFixedDelay(this::drain, DRAIN_INTERVAL_SECONDS, DRAIN_INTERVAL_SECONDS, TimeUnit.SECONDS);
	}

	public static String siteUrl()
	{
		final String override = System.getProperty("triglav.siteUrl");
		return override == null || override.trim().isEmpty() ? DEFAULT_SITE_URL : override.trim();
	}

	/** @return true once the clan code has been exchanged for an ingest key */
	public boolean isPaired()
	{
		return keyStore.isLinked();
	}

	/**
	 * Queues a Dink-shaped event for delivery. Safe to call from any thread.
	 *
	 * @param screenshot WebP bytes, or null to send without one
	 */
	public synchronized void send(JsonObject envelope, byte[] screenshot)
	{
		if (!isPaired())
		{
			return;
		}

		if (!envelope.has("playerName") || envelope.get("playerName").getAsString().isEmpty())
		{
			log.debug("Not sending {} without a player name", envelope.has("type") ? envelope.get("type").getAsString() : "?");
			return;
		}

		if (queue.size() >= MAX_QUEUE)
		{
			final QueuedEvent dropped = queue.pollFirst();
			log.warn("Ingest queue full, dropping oldest event: {}", dropped == null ? "?" : dropped.type);
		}

		queue.addLast(new QueuedEvent(envelope, screenshot));
	}

	private void drain()
	{
		QueuedEvent event;
		synchronized (this)
		{
			event = queue.pollFirst();
		}

		if (event == null)
		{
			return;
		}

		if (deliver(event))
		{
			return;
		}

		event.attempts++;
		if (event.attempts < MAX_ATTEMPTS)
		{
			synchronized (this)
			{
				queue.addFirst(event);
			}
		}
		else
		{
			log.warn("Giving up on event after {} attempts: {}", event.attempts, event.type);
		}
	}

	private boolean deliver(QueuedEvent event)
	{
		final String key = keyStore.ingestKey();
		if (key == null)
		{
			return false;
		}

		final HttpUrl url = HttpUrl.parse(siteUrl() + "/api/dink/" + key);
		if (url == null)
		{
			log.warn("Invalid site URL, cannot deliver {}", event.type);
			return false;
		}

		final RequestBody body = event.screenshot == null
			? RequestBody.create(JSON, event.json.toString())
			: new MultipartBody.Builder()
				.setType(MultipartBody.FORM)
				.addFormDataPart("payload_json", event.json.toString())
				.addFormDataPart("file", "screenshot.png", RequestBody.create(PNG, event.screenshot))
				.build();

		final Request request = new Request.Builder().url(url).post(body).build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (response.isSuccessful())
			{
				return true;
			}

			final String reason = response.body() == null ? "" : response.body().string();
			log.warn("Ingest rejected {} with HTTP {}: {}", event.type, response.code(),
				reason.length() > 300 ? reason.substring(0, 300) : reason);
			// A 4xx other than 429 means this event itself is invalid; retrying it can't help.
			return response.code() >= 400 && response.code() < 500 && response.code() != 429;
		}
		catch (IOException e)
		{
			log.debug("Ingest unreachable for {}: {}", event.type, e.getMessage());
			return false;
		}
	}

	private static final class QueuedEvent
	{
		final String type;
		final JsonObject json;
		final byte[] screenshot;
		int attempts;

		QueuedEvent(JsonObject json, byte[] screenshot)
		{
			this.json = json;
			this.type = json.has("type") ? json.get("type").getAsString() : "?";
			this.screenshot = screenshot;
		}
	}
}

package com.triglav.clan.net;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Fetches GET /api/plugin/config/:key on startup, right after linking and then hourly, so a change
 * on the site (e.g. the screenshot threshold) reaches every plugin within the hour without a restart.
 * docs/plugin-brief.md §4 said 6h; an hour is still one tiny request per member.
 */
@Slf4j
@Singleton
public class ConfigClient
{
	private static final long REFRESH_HOURS = 1;

	private final OkHttpClient httpClient;
	private final KeyStore keyStore;
	private final ScheduledExecutorService executor;
	private final AtomicReference<RemoteConfig> current = new AtomicReference<>(RemoteConfig.DEFAULT);

	@Inject
	private ConfigClient(OkHttpClient httpClient, KeyStore keyStore, ScheduledExecutorService executor)
	{
		this.httpClient = httpClient;
		this.keyStore = keyStore;
		this.executor = executor;
		executor.scheduleWithFixedDelay(this::refresh, 0, REFRESH_HOURS, TimeUnit.HOURS);
	}

	public RemoteConfig current()
	{
		return current.get();
	}

	public void refreshNow()
	{
		executor.execute(this::refresh);
	}

	private void refresh()
	{
		final String clanCode = keyStore.ingestKey();
		if (clanCode == null)
		{
			return;
		}

		final HttpUrl url = HttpUrl.parse(ApiClient.siteUrl() + "/api/plugin/config/" + clanCode);
		if (url == null)
		{
			return;
		}

		final Request request = new Request.Builder().url(url).build();
		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful() || response.body() == null)
			{
				return;
			}

			final JsonObject body = new JsonParser().parse(response.body().string()).getAsJsonObject();
			final int screenshotMinValue = body.has("screenshotMinValue") ? body.get("screenshotMinValue").getAsInt() : RemoteConfig.DEFAULT.screenshotMinValue;
			final int pollSeconds = body.has("pollSeconds") ? body.get("pollSeconds").getAsInt() : RemoteConfig.DEFAULT.pollSeconds;
			current.set(new RemoteConfig(screenshotMinValue, pollSeconds));
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Could not refresh remote config: {}", e.getMessage());
		}
	}
}

package com.triglav.clan.net;

import com.google.gson.JsonObject;
import net.runelite.api.Client;
import net.runelite.api.Player;

/**
 * The envelope every ingest event shares (site: src/lib/dink/schema.ts). Kept identical to
 * what Dink sends so the site's existing parser needs no changes. The site rejects an empty
 * `playerName`, so callers that may run without a loaded local player (logout) pass the name in.
 */
public final class Envelope
{
	private Envelope()
	{
	}

	/** @return the local player's name, or null while the player isn't loaded (login screen, first login ticks) */
	public static String playerName(Client client)
	{
		final Player local = client.getLocalPlayer();
		final String name = local == null ? null : local.getName();
		return name == null || name.isEmpty() ? null : name;
	}

	public static JsonObject create(Client client, String type, JsonObject extra)
	{
		return create(client, type, extra, playerName(client));
	}

	public static JsonObject create(Client client, String type, JsonObject extra, String playerName)
	{
		final JsonObject envelope = new JsonObject();
		envelope.addProperty("type", type);
		envelope.addProperty("playerName", playerName == null ? "" : playerName);
		envelope.addProperty("accountType", client.getAccountType().name());
		envelope.addProperty("dinkAccountHash", Long.toString(client.getAccountHash()));
		envelope.addProperty("world", client.getWorld());
		envelope.add("extra", extra == null ? new JsonObject() : extra);
		return envelope;
	}
}

package com.triglav.clan.net;

/** Snapshot of GET /api/plugin/config/:key (docs/plugin-brief.md §4). */
public final class RemoteConfig
{
	public static final RemoteConfig DEFAULT = new RemoteConfig(500_000, 60);

	public final int screenshotMinValue;
	public final int pollSeconds;

	public RemoteConfig(int screenshotMinValue, int pollSeconds)
	{
		this.screenshotMinValue = screenshotMinValue;
		this.pollSeconds = pollSeconds;
	}
}
